"","Reason":null,"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"التعويض بـ8 يعطي 56، وليس 50.","En":"Substitution of 8 gives 56, not 50."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"التعويض بـ10 يعطي 68، وليس 50.","En":"Substitution of 10 gives 68, not 50."},"Order":4}]}$mw$,$mw$مبدأ توازن المعادلة: نزيل الجمع أولاً ثم الضرب.

